SELECT *, INET_NTOA(static_rule_sip) as static_rule_sip_d, INET_NTOA(static_rule_msip) as static_rule_msip_d, INET_NTOA(static_rule_dip) as static_rule_dip_d, INET_NTOA(static_rule_mdip) as static_rule_mdip_d, task_name as used_task_name FROM t_static_rule left join t_task on t_static_rule.static_rule_used_task_id = t_task.task_id
static_rule_name like concat('%', #{static_rule_name}, '%')
AND static_rule_display_id like concat('%', #{static_rule_id}, '%')
AND static_rule_create_username like concat('%', #{static_rule_create_username}, '%')
AND ((static_rule_msip IS NULL AND static_rule_sip = INET_ATON(#{sip})) OR ( static_rule_msip IS NOT NULL AND ( static_rule_sip & static_rule_msip) = (INET_ATON(#{sip}) & static_rule_msip) ) )
AND ((static_rule_mdip IS NULL AND static_rule_dip = INET_ATON(#{dip})) OR ( static_rule_mdip IS NOT NULL AND ( static_rule_dip & static_rule_mdip) = (INET_ATON(#{dip}) & static_rule_mdip) ) )
AND static_rule_sport = #{sport}
AND static_rule_dport = #{dport}
AND static_rule_audit_status = #{auditStatus}
AND audit_user_name like concat('%', #{auditUserName}, '%')
AND static_rule_create_time like concat('%', #{createDate}, '%')
ORDER BY static_rule_id DESC LIMIT ${(page - 1) * pageSize}, #{pageSize}

